import{_ as t,c as e,o as r,b0 as s}from"./chunks/framework.Dmsv_Tiv.js";const o="data:image/png;base64,",i="/media-docs/assets/image-20251218104849901.CLCMbzJK.jpg",p="/media-docs/assets/image-20251218105030443.BEWDV6Bi.jpg",n="/media-docs/assets/image-20251218105158476.CdGyBadc.jpg",m="/media-docs/assets/image-20251218105401667.DX_M-8QS.jpg",l="/media-docs/assets/image-20251218110019740.CHRWf3zq.jpg",d="/media-docs/assets/image-20251218110133979.BYN5nStZ.png",h="/media-docs/assets/image-20251218110152756.SrMNOI63.png",g="/media-docs/assets/image-20251218110211636.JF5tKNNo.png",A="/media-docs/assets/YCbCr-CbCr_Scaled_Y50.krzT0IrJ.png",c="data:image/png;base64,",k="/media-docs/assets/raw-yuv-1-4.D1FfYLCM.png",T=JSON.parse('{"title":"LV010-YUV简介","description":null,"frontmatter":{"title":"LV010-YUV简介","date":"2025-09-19T09:43:21.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/color-model/126b08d6c8310b36faa21609","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-09-19T09:43:21.179Z","fulluuid":"6faa21609f87414c823bac88a27dec71","useduuid":"6faa21609"}},"headers":[],"relativePath":"sdoc/image/color-model/126b08d6c8310b36faa21609.md","filePath":"sdoc/01-图像/20-常用色彩模型/LV010-YUV简介.md","lastUpdated":1767537778000}'),b={name:"sdoc/image/color-model/126b08d6c8310b36faa21609.md"};function N(u,a,C,Y,V,R){return r(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="lv010-yuv简介" tabindex="-1">LV010-YUV简介 <a class="header-anchor" href="#lv010-yuv简介" aria-label="Permalink to &quot;LV010-YUV简介&quot;">​</a></h1><p>其实这一节的笔记是为后面的视频学习做铺垫，视频数据也是由一帧一帧的图像组成，在国内，一般都是使用25fps，就是1秒钟25帧图像，由于人眼的视觉停留，所以我们看到的画面就是运动的了。在视频原始数据中，常见的采样格式有YUV444、YUV420、RGB等。</p><h2 id="一、什么是yuv" tabindex="-1">一、什么是YUV？ <a class="header-anchor" href="#一、什么是yuv" aria-label="Permalink to &quot;一、什么是YUV？&quot;">​</a></h2><h3 id="_1-yuv简介" tabindex="-1">1. yuv简介 <a class="header-anchor" href="#_1-yuv简介" aria-label="Permalink to &quot;1. yuv简介&quot;">​</a></h3><p><a href="https://www.wikiwand.com/zh-hans/YUV" target="_blank" rel="noreferrer">YUV</a>，是一种<a href="https://www.wikiwand.com/zh-hans/%E9%A1%8F%E8%89%B2" target="_blank" rel="noreferrer">颜色</a><a href="https://www.wikiwand.com/zh-hans/%E7%B7%A8%E7%A2%BC" target="_blank" rel="noreferrer">编码</a>方法。常使用在各个影像处理元件中。之前了解的RGB 色彩空间更适合图像采集和显示， YUV 空间用于编码和存储则比较好。在存储和编码之前，RGB 图像要转换为 YUV 图像，而 YUV 图像在 显示之前<strong>通常</strong>有必要转换回 RGB。</p><p>YUV 色彩空间在音视频开发，编码压缩领域更加常用。常用的原因主要是涉及到 HVS （Human Visual System）人类视觉系统 对 色彩空间的感知能力。</p><p>视觉心理学研究表明，人的视觉系统对光的感知程度可以用两个属性来描述：**亮度（luminance）**跟 <strong>色度（chrominance）</strong>，这里的色度也叫做 饱和度或彩度，总之 色度的叫法有很多，要注意上下文来区分语义。</p><p>然后 <strong>色度感知</strong> 包含两个维度：<strong>色调</strong>（Hue）和 <strong>色饱和度</strong>（saturation）。色调是由光波的峰值定义的，描述的是光的颜色。色饱和度是由光波的谱宽定义的，描述的是光的纯度。</p><p>因此 HVS 对色彩的感知主要有 3个属性：亮度（luminance），色调（Hue）和 色饱和度（saturation）。也就是 YUV 色彩空间，Y 代表 亮度，U代表色调，V代表色饱和度。</p><p>经过大量研究实验表明，<strong>视觉系统 对 色度 的敏感度 是远小于 亮度的</strong>。所以可以对 色度 采用更小的采样率来压缩数据，对亮度采用正常的采样率即可，这样压缩数据不会对视觉体验产生太大的影响。简单来说就是用更少的数据/信息来表达 色度（chroma），用更多的数据/信息来表达 亮度（luminance）。</p><h3 id="_2-hvs-是怎么感知-yuv" tabindex="-1">2. HVS 是怎么感知 YUV？ <a class="header-anchor" href="#_2-hvs-是怎么感知-yuv" aria-label="Permalink to &quot;2. HVS 是怎么感知 YUV？&quot;">​</a></h3><p>首先我们需要一张YUV图片：<a href="https://wwz.lanzouj.com/iZ6EU22ehwcf" target="_blank" rel="noreferrer">meigui_yuv_444.rar</a>，下载完毕后解压，我们会得到这样一张yuv格式的图片，但是是打不开的：</p><img src="'+o+'" alt="image-20240622101759453" style="zoom:50%;"><p>用什么打开？我们需要用支持YUV数据查看的软件，如<a href="https://gitee.com/QQxiaoming/YUVviewer" target="_blank" rel="noreferrer">YUVviewer: YUVviewer (gitee.com)</a>、<a href="https://sourceforge.net/projects/raw-yuvplayer/" target="_blank" rel="noreferrer">YUV Player</a>和<a href="http://datahammer.de/downloads.html" target="_blank" rel="noreferrer">7yuv</a>等，7yuv这个软件好像是要收费，功能比较多，网上随便找找，都有绿色版本，YUVviewer还带自己编译，YUV Player的话只能单独查看Y分量吧我记得，反正后来没有用。最后我用的是这个7zyuv:</p><img src="'+i+'" alt="image-20251218104849901" style="zoom:50%;"><p>打开<a href="https://wwz.lanzouj.com/iZ6EU22ehwcf" target="_blank" rel="noreferrer">meigui_yuv_444</a>这个文件，打开后要配置一下，左边的Format中选择YUV444 planar，长宽选择650x487，右侧的YUV全部勾选，就可以看到彩色的图片啦。我们若是只勾选了 Y 分量显示，可以看到是一个黑白图像，<strong>Y 是亮度，黑色越亮就会变成灰色，灰色越亮就会变成白色</strong>。</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+p+'" alt="image-20251218105030443" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+n+'" alt="image-20251218105158476" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+m+'" alt="image-20251218105401667" style="width:100%;height:auto;"></td></tr></tbody></table><p>然后我们只勾选 Y 跟 U 两个分量，注意看叶子跟花朵，可以看出来，已经能看到绿色跟红色了，但是他们非常原始，是暗红跟暗绿的颜色。最后，把 V （色饱和度）也勾上，可以看到，暗红 变成了玫瑰红，暗绿 变成了 青绿色。</p><blockquote><p>为什么 RGB 色彩空间不符合 HVS 的感知能力</p></blockquote><p>我们来看一张图片<a href="https://wwz.lanzouj.com/izHAh22eqkoj" target="_blank" rel="noreferrer">juren.rar</a>，里面是 RGB24 真彩色数据。然后同样用刚才的7yuv打开：</p><img src="'+l+'" alt="image-20251218110019740" style="zoom:67%;"><p>我们分别只勾选RGB，来看一下效果：</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+d+'" alt="image-20251218110133979" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+h+'" alt="image-20251218110152756" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+g+`" alt="image-20251218110211636" style="width:100%;height:auto;"></td></tr></tbody></table><p>可以看到蓝色明显更暗，其他两个更亮一些，<strong>这 3 个 分量都跟 亮度密切相关</strong>，所以针对 HVS 的压缩技巧，在 RGB 色彩空间 不方便使用。</p><h2 id="二、yuv的分类" tabindex="-1">二、YUV的分类？ <a class="header-anchor" href="#二、yuv的分类" aria-label="Permalink to &quot;二、YUV的分类？&quot;">​</a></h2><h3 id="_1-ycbcr简介" tabindex="-1">1. YCbCr简介 <a class="header-anchor" href="#_1-ycbcr简介" aria-label="Permalink to &quot;1. YCbCr简介&quot;">​</a></h3><p>在网上还会看到一些其他的描述：Y&#39;UV、YUV、YCbCr、YPbPr 等。由于历史关系，Y&#39;UV、YUV 主要是用在彩色电视中，用于模拟信号表示。YCbCr 是用在数字视频、图像的压缩和传输，如 MPEG、JPEG。今天我们所讲的 YUV 其实就是指 <a href="https://www.wikiwand.com/zh-hans/YCbCr" target="_blank" rel="noreferrer">YCbCr</a>。其中 Y 表示亮度（luma），CbCr 表示色度（chroma）。其实 Y 是明亮度，用来表示像素的灰度值，U、V 分别是影像色彩与饱和度，用来表示像素的颜色。总的来说它其实与RGB一样表示一个像素点的颜色，RGB和YUV之间是可以互相转换的。</p><table tabindex="0"><thead><tr><th>分量</th><th>说明</th></tr></thead><tbody><tr><td>Y</td><td>表示亮度分量，如果只显示Y的话，图像看起来会是一张黑白照。</td></tr><tr><td>U（Cb）</td><td>表示蓝色色度分量：是照片蓝色部分去掉亮度（Y）。</td></tr><tr><td>V（Cr）</td><td>表示红色色度分量：是照片红色部分去掉亮度（Y）。</td></tr></tbody></table><p>总的来说，YUV 其实目前有 三种分类：</p><ul><li>YIQ，适用于NTSC彩色电视制式</li><li>YUV，适用于PAL和SECAM彩色电视制式</li><li>YCbCr，适用于计算机用的显示器</li></ul><p>互联网音视频开发中 一般说的 YUV 是 指 <strong>YCbCr</strong> ，U 就是 Cb，V 就是 Cr。我们会经常在一些音视频书籍看到 YCbCr ，把它当成是 YUV 就行。<strong>实际上 YCbCr 才是比较准确的术语</strong>，JPEG、MPEG 标准 用的也是 YCbCr 。后面学习的 YUV 也是指 YCbCr ，不是指 用于PAL和SECAM彩色电视 的 YUV。</p><h3 id="_2-ycbcr中的cbcr" tabindex="-1">2. YCbCr中的CbCr <a class="header-anchor" href="#_2-ycbcr中的cbcr" aria-label="Permalink to &quot;2. YCbCr中的CbCr&quot;">​</a></h3><p>我们来看一下CbCr 这两个通道信息。YUV 里面的 U 就是 Cb ，术语是 <strong>色调</strong>（Hue）。V 就是 Cr ，术语是 <strong>色饱和度</strong>（saturation）。实际上可以把 UV 看成是 ，colour difference （色彩的差异），可以看下面三个公式：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Cb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Blue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Y</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Red</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Y</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Cg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Green</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Y</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Cb 代表 蓝色 色度的分量，是通过 RGB 里面的 B 的值 减去 Y 的值得到的。Cr 代表 红色 色度的分量，是通过 RGB 里面的 R 的值 减去 Y 的值得到的。Cg 代表 绿色色 色度的分量，是通过 RGB 里面的 G 的值 减去 Y 的值得到的。Cb 跟 Cr 的颜色空间 如下图:</p><img src="`+A+'" alt="YCbCr-CbCr_Scaled_Y50" style="zoom:8%;"><p>为了直观感受 CbCr 值的影响，需要使用一个 YUV 调色板来演示一下，如下图：</p><img src="'+c+'" alt="img" style="zoom:50%;"><p>上图中，YUV 的值都是 1 ~ 255 ，所以 128 就是上图 x y轴的中心。可以试着把 Y 从 0 改成 255，会越来越<strong>亮</strong> ，直到变成白色。调色板里面的 U 就是 Cb，这个值 就是 彩色空间 x 轴的偏移位置，也就是差值，偏移这么多就能达到想要的颜色。但是 还有 Y 轴，Y 轴是 Cr。Cb 跟 Cr 是组合的，会互相影响最后的颜色。所以， Cr 跟 Cb 在 X Y 轴的图片上看，就会很容易理解他们的作用。</p><blockquote><ul><li>调色板下载链接：<a href="https://pan.baidu.com/s/1RyuPYs9eXmxtZ7CrMTl65w?pwd=b2d9" target="_blank" rel="noreferrer">YUV调色板</a></li></ul><p>这个调色板是 <a href="https://lin-lz.blog.csdn.net/" target="_blank" rel="noreferrer">岳麓吹雪</a> 用MFC 写的（原文章在这里<a href="https://blog.csdn.net/lin453701006/article/details/79734561" target="_blank" rel="noreferrer">YUV调色板软件_yuv在线调色板-CSDN博客</a>），需要安装 VS2017 跟 MFC 组件，因为这个项目比较旧，需要改一下配置，如下图，把 Platform Toolset 换成 v2017：</p><img src="'+k+'" alt="img" style="zoom:50%;"><p>我没装这些组件，后面也没试，等有需要再说吧。</p></blockquote><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/leixiaohua1020/article/details/50534150" target="_blank" rel="noreferrer">视音频数据处理入门：RGB、YUV像素数据处理_视频基本原理--rgb to yuv&amp;ycbcr-CSDN博客</a></p></blockquote>',41)])])}const G=t(b,[["render",N]]);export{T as __pageData,G as default};
